"""The Lie (super)algebra generated by the Chevalley generators of g(A) acting in an
irreducible module L^lambda (hwmod.py), p = 2, over GF(2^K); graded by the root lattice.
Output: per-degree dims (root multiplicities), sdim for a parity vector, whether 1_L is in
the degree-0 part (a center acting by scalars)."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hwmod
from gf2k import GFField

def module_mats(A, par, lam, F):
    M = hwmod.HWModule(A, par, 2, lam, field=F, maxdim=4000, maxheight=60)
    degs = sorted([d for d, m in M.dim.items() if m], key=lambda d: (sum(d), d))
    off = {}; N = 0
    for d in degs:
        off[d] = N; N += M.dim[d]
    n = len(A)
    E = [[[0] * N for _ in range(N)] for _ in range(n)]
    Fm = [[[0] * N for _ in range(N)] for _ in range(n)]
    for (d, k), mat in M.E.items():
        dk = list(d); dk[k] -= 1; dk = tuple(dk)
        if M.dim.get(d, 0) == 0 or M.dim.get(dk, 0) == 0: continue
        for a, row in enumerate(mat):
            for b, x in enumerate(row):
                if x.v: E[k][off[dk] + a][off[d] + b] = x.v
    for (d, j), mat in M.F.items():
        dj = list(d); dj[j] -= 1; dj = tuple(dj)
        if M.dim.get(d, 0) == 0 or M.dim.get(dj, 0) == 0: continue
        for a, row in enumerate(mat):
            for b, x in enumerate(row):
                if x.v: Fm[j][off[d] + a][off[dj] + b] = x.v
    return N, E, Fm

class Ech:
    """echelon basis over GF(2^K), vectors as lists of ints"""
    def __init__(s, F):
        s.F = F; s.rows = []   # (pivot, vec normalized)
    def reduce(s, v):
        v = list(v); F = s.F
        for p, r in s.rows:
            c = v[p]
            if c:
                v = [x ^ F.mul(c, y) for x, y in zip(v, r)]
        return v
    def add(s, v):
        v = s.reduce(v)
        for p, x in enumerate(v):
            if x:
                iv = s.F.inv_(x)
                v = [s.F.mul(iv, y) for y in v]
                s.rows = [(q, [a ^ s.F.mul(r[p], b) for a, b in zip(r, v)]) if r[p] else (q, r) for q, r in s.rows]
                s.rows.append((p, v)); return True
        return False
    def __len__(s): return len(s.rows)

def mm(F, X, Y):
    N = len(X); Z = [[0] * N for _ in range(N)]
    for i in range(N):
        Xi = X[i]; Zi = Z[i]
        for k in range(N):
            a = Xi[k]
            if a:
                Yk = Y[k]
                for j in range(N):
                    if Yk[j]: Zi[j] ^= F.mul(a, Yk[j])
    return Z

def br(F, X, Y):
    A = mm(F, X, Y); B = mm(F, Y, X)
    return [[a ^ b for a, b in zip(r, s)] for r, s in zip(A, B)]

flat = lambda X: [x for r in X for x in r]
unflat = lambda v, N: [v[i * N:(i + 1) * N] for i in range(N)]

def generate(A, par, lam, F, squares=True):
    n = len(A)
    N, E, Fm = module_mats(A, par, lam, F)
    spaces = {}   # degree -> Ech
    elems = {}    # degree -> list of matrices (basis)
    queue = []
    def put(d, X):
        e = spaces.setdefault(d, Ech(F))
        if e.add(flat(X)):
            elems.setdefault(d, []).append(X); queue.append((d, X)); return True
        return False
    for k in range(n):
        put(tuple(1 if i == k else 0 for i in range(n)), E[k])
        put(tuple(-1 if i == k else 0 for i in range(n)), Fm[k])
    gens = list(queue)
    while queue:
        d, X = queue.pop()
        for d2, Y in gens:
            dd = tuple(a + b for a, b in zip(d, d2))
            put(dd, br(F, X, Y))
        if squares and sum(a * b for a, b in zip(d, par)) % 2:
            put(tuple(2 * a for a in d), mm(F, X, X))
    # ideal generated by the e,f with themselves: bracket with generators suffices for g'(A)
    ident = flat([[1 if i == j else 0 for j in range(N)] for i in range(N)])
    z = tuple([0] * n)
    central = z in spaces and not any(spaces[z].reduce(ident))
    return N, {d: len(e) for d, e in spaces.items()}, elems, central

def sdim(dims, par):
    ev = od = 0
    for d, m in dims.items():
        if sum(a * b for a, b in zip(d, par)) % 2: od += m
        else: ev += m
    return ev, od
